questionvariables.text:
/*general and fertility rates*/
age:5;
age_group1:rand_with_step(14,16,5);
age_group2:age_group1+age;
age_group3:age_group2+age;
age_group4:age_group3+age;
age_group5:age_group4+age;
age_group6:age_group5+age;
age_group7:age_group6+age;
age_group8:age_group7+age;

/*number of women*/
diff:rand(5)+5;
no_women:rand_with_step(80,150,10);
no_women1:rand_with_step(80,150,10);
no_women2:rand_with_step(80,150,10);
no_women3:rand_with_step(80,150,10);
no_women4:rand_with_step(80,130,10);
no_women5:rand_with_step(80,130,10);
no_women6:rand_with_step(80,120,10);
no_women7:rand_with_step(80,100,10);

/*fertility rates*/
fert_diff:rand(10)+10;
fertility_rate:rand_with_step(160,210,10);
fertility_rate1:rand_with_step(170,220,10);
fertility_rate2:rand_with_step(180,230,10);
fertility_rate3:rand_with_step(190,240,10);
fertility_rate4:rand_with_step(190,250,10);
fertility_rate5:rand_with_step(190,240,10);
fertility_rate6:rand_with_step(180,230,10);
fertility_rate7:rand_with_step(170,220,10);


/*number of children born*/
no_kids_born1:decimalplaces((no_women1*fertility_rate1)/1000,1);
no_kids_born2:decimalplaces((no_women2*fertility_rate2)/1000,1);
no_kids_born3:decimalplaces((no_women3*fertility_rate3)/1000,1);
no_kids_born4:decimalplaces((no_women4*fertility_rate4)/1000,1);
no_kids_born5:decimalplaces((no_women5*fertility_rate5)/1000,1);
no_kids_born6:decimalplaces((no_women6*fertility_rate6)/1000,1);
no_kids_born7:decimalplaces((no_women7*fertility_rate7)/1000,1);

/*worked solution variables*/
sum_women:no_women1+no_women2+no_women3+no_women4+no_women5+no_women6+no_women7;
sum_fertility:fertility_rate1+fertility_rate2+fertility_rate3+fertility_rate4+fertility_rate5+fertility_rate6+fertility_rate7;
sum_kids:no_kids_born1+no_kids_born2+no_kids_born3+no_kids_born4+no_kids_born5+no_kids_born6+no_kids_born7;
/*model answers*/
grr:decimalplaces((sum_kids/sum_women)*1000,2);/*general fertility rate*/
total_fertilityrate:sum_fertility*age;
